import { Metadata } from "next";
import { myFetch } from "@/helpers/myFetch";
import Link from "next/link";

export const metadata: Metadata = {
  title: "Premium Subscription - Viva Leve",
  description: "Upgrade to Viva Leve Premium",
};

interface Package {
  _id: string;
  title: string;
  price: number;
  duration: string; // e.g. "1 month", "3 months", "6 months"
  paymentType: string;
  productId: string;
  priceId: string;
  paymentLink: string;
  status: string;
}

export default async function SubscriptionPage() {
  const res = await myFetch<Package[]>("/package", {
    method: "GET",
    next: { tags: ["packages"] },
  });

  const packages = res.data || [];

  // Sort packages by duration logically (1 month, 3 months, 6 months)
  const sortedPackages = [...packages].sort((a, b) => {
    const numA = parseInt(a.duration) || 0;
    const numB = parseInt(b.duration) || 0;
    return numA - numB;
  });

  return (
    <div className="container mx-auto px-4 py-16 max-w-5xl">
      <div className="text-center mb-16">
        <h1 className="text-2xl font-bold tracking-tight mb-6 text-brand">PREMIUM</h1>
        <p className="text-muted-foreground max-w-3xl mx-auto leading-relaxed text-[15px]">
          // eslint-disable-next-line react/no-unescaped-entities
          Since our company's founding in 2001 in Silicon Valley, we have specialized in online dating, connecting
          // eslint-disable-next-line react/no-unescaped-entities
          millions of couples with our trusted services for over 25 years. We've invested more than $10 million in
          our infrastructure to enhance online dating for seamless, successful connections.
        </p>
      </div>

      <div className="grid md:grid-cols-3 gap-6 items-end mt-12 max-w-4xl mx-auto">
        {sortedPackages.map((pkg) => {
          const months = parseInt(pkg.duration) || 1;

          let badge = null;
          if (months === 3) badge = "Most Popular";
          if (months === 6) badge = "Best Deal";

          const isPrimary = months === 1;

          return (
            <Link 
              key={pkg._id} 
              href={pkg.paymentLink || "#"}
              className={`relative bg-white flex flex-col justify-center text-center cursor-pointer hover:shadow-lg transition-shadow p-10 h-64 mt-8 md:mt-0 ${
                isPrimary 
                  ? "border-2 border-brand" 
                  : "border border-border shadow-sm rounded-sm"
              }`}
            >
              {badge && (
                <div className="absolute -top-4 left-1/2 -translate-x-1/2 bg-brand text-brand-foreground text-[13px] px-4 py-1 rounded-full whitespace-nowrap shadow-sm font-medium">
                  {badge}
                </div>
              )}
              <h2 className={`text-xl font-medium mb-8 ${isPrimary ? "text-brand" : "text-foreground"}`}>
                {pkg.duration}
              </h2>
              <p className="text-lg font-bold text-foreground">
                USD ${pkg.price}
              </p>
              {pkg.paymentType && (
                <p className="text-muted-foreground mt-2 text-[15px]">
                  {pkg.paymentType}
                </p>
              )}
            </Link>
          );
        })}
        {sortedPackages.length === 0 && (
          <div className="col-span-3 text-center text-muted-foreground">
            No premium packages available at the moment.
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useRef } from "react";
import { Smile, Paperclip, Send, X, Plus } from "lucide-react";
import { toast } from "sonner";
import { myFetch } from "@/helpers/myFetch";
import { useRouter } from "next/navigation";
import { revalidateTags } from "@/helpers/revalidateTags";
import EmojiPicker, { EmojiClickData } from "emoji-picker-react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

export function ChatInput({
  chatId,
  activeUser,
  profile,
}: {
  chatId: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  activeUser: any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  profile: any;
}) {
  // console.log(activeUser, 'chat input')
  const inputRef = useRef<HTMLInputElement>(null);
  const router = useRouter();
  const [text, setText] = useState("");
  const [files, setFiles] = useState<File[]>([]);
  const [isSending, setIsSending] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(e.target.files || []);
    if (selectedFiles.length + files.length > 5) {
      toast.error("You can only send up to 5 images at once");
      return;
    }
    setFiles((prev) => [...prev, ...selectedFiles]);
  };

  const removeFile = (index: number) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSend = async () => {
    if (!text.trim() && files.length === 0) return;

    setIsSending(true);
    const formData = new FormData();
    formData.append("text", text);
    formData.append("chatId", chatId);
    formData.append("type", "text");

    files.forEach((file) => {
      formData.append("image", file);
    });

    try {
      const res = await myFetch("/message", {
        method: "POST",
        body: formData,
      });
      // console.log(res)
      if (res?.success) {
        setText("");
        setFiles([]);
        revalidateTags(["message"]);
        router.refresh();
        setTimeout(() => {
          inputRef.current?.focus();
        }, 100);
      } else if (
        res?.message === "You don't have enough credit to send messages" ||
        res?.message === "blocked by user"
      ) {
        toast.error(res.message);

        setTimeout(() => {
          window.location.reload();
        }, 300);

        return;
      } else {
        toast.error(res?.message || "Failed to send message");
      }
    } catch (error) {
      toast.error("Something went wrong");
      console.error(error);
    } finally {
      setIsSending(false);
    }
  };



  const onEmojiClick = (emojiData: EmojiClickData) => {
    setText((prev) => prev + emojiData.emoji);
  };

  const isBlocked = activeUser?.status === "block";
  const iBlockedThem = activeUser?.blockByMe === true;
  const theyBlockedMe = isBlocked && !iBlockedThem;


  return (
    <div className="px-5 py-4 border-t border-gray-200 bg-white relative z-20">
      {/* File Previews */}
      {files.length > 0 && (
        <div className="flex flex-wrap gap-2 mb-3 bg-gray-50 p-3 rounded-2xl border border-gray-200">
          {files.map((file, i) => (
            <div
              key={i}
              className="relative w-16 h-16 rounded-xl overflow-hidden border border-gray-200 group"
            >
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={URL.createObjectURL(file)}
                alt=""
                className="w-full h-full object-cover"
              />
              <button
                onClick={() => removeFile(i)}
                className="absolute top-1 right-1 w-5 h-5 rounded-full bg-black/60 flex items-center justify-center text-white/70 hover:text-white transition-colors"
              >
                <X size={12} />
              </button>
            </div>
          ))}
          <button
            onClick={() => fileInputRef.current?.click()}
            className="w-16 h-16 rounded-xl border border-dashed border-gray-300 flex items-center justify-center text-gray-400 hover:text-gray-600 hover:border-gray-400 transition-all"
          >
            <Plus size={20} />
          </button>
        </div>
      )}

      {/* Main Bar */}
      <div
        className={`flex items-center gap-3 border rounded-2xl px-4 py-2.5 shadow-sm transition-all group
  ${
    isBlocked
      ? "bg-gray-100 border-gray-200 opacity-50 cursor-not-allowed"
      : "bg-gray-50 border-gray-200 focus-within:border-[#429CA8]/40"
  }`}
      >
        <Popover>
          <PopoverTrigger asChild>
            <button
              disabled={isBlocked}
              className="text-gray-400 hover:text-[#429CA8] transition-colors shrink-0 disabled:pointer-events-none disabled:text-gray-300"
            >
              <Smile size={20} />
            </button>
          </PopoverTrigger>

          <PopoverContent
            side="top"
            align="end"
            className="p-0 border-none bg-transparent"
          >
            <EmojiPicker onEmojiClick={onEmojiClick} />
          </PopoverContent>
        </Popover>

        <input
          type="text"
          ref={inputRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && !e.shiftKey && handleSend()}
          placeholder={
            iBlockedThem
              ? "Unblock this user to send messages..."
              : theyBlockedMe
                ? "You cannot reply in this conversation..."
                : "Type a message..."
          }
          disabled={isSending || isBlocked}
          className="flex-1 bg-transparent text-gray-900 text-[14px] placeholder-gray-400 focus:outline-none min-w-0 font-normal disabled:cursor-not-allowed"
        />

        <div className="flex items-center gap-2 border-l border-gray-200 pl-3">
          {activeUser?.remaningMessage !== undefined &&
            profile?.role === "FAN" && (
              <Tooltip>
                <TooltipTrigger asChild disabled={isSending || isBlocked}>
                  <div className="flex items-center justify-center min-w-[20px] h-6 px-1.5 rounded-md bg-white border border-gray-200 cursor-help hover:border-[#429CA8]/30 hover:bg-[#429CA8]/5 transition-all group/credit">
                    <span className="text-[10px] font-bold text-gray-500 group-hover/credit:text-[#429CA8] transition-colors">
                      {activeUser.remaningMessage}
                    </span>
                  </div>
                </TooltipTrigger>
                <TooltipContent
                  side="top"
                  className="bg-white border-gray-200 text-gray-700 shadow-sm"
                >
                  <p className="text-xs font-medium">
                    Remaining messages:{" "}
                    <span className="text-gray-900">
                      {activeUser.remaningMessage}
                    </span>
                  </p>
                </TooltipContent>
              </Tooltip>
            )}

          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            className="hidden"
            multiple
            accept="image/*"
          />
          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={isBlocked}
            className="text-gray-400 hover:text-[#429CA8] transition-colors shrink-0 disabled:pointer-events-none disabled:text-gray-300"
          >
            <Paperclip size={18} />
          </button>

          <button
            onClick={handleSend}
            disabled={
              isSending || (!text.trim() && files.length === 0) || isBlocked
            }
            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all shrink-0
        ${
          isSending || (!text.trim() && files.length === 0) || isBlocked
            ? "bg-gray-200 text-gray-400 cursor-not-allowed"
            : "bg-[#429CA8] text-white hover:bg-[#347A83] shadow-sm active:scale-95"
        }`}
          >
            {isSending ? (
              <span className="w-4 h-4 rounded-full border-2 border-white/30 border-t-white animate-spin" />
            ) : (
              <Send size={15} />
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

