// @/components/settings/tabs/DeletedMembersTab.tsx
"use client";

import { useState, useEffect } from "react";
import { Search, Ban, Loader2 } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { getBlockedMembers, unblockUser } from "../action";
import { toast } from "sonner";
import { avatarUrl } from "@/lib/image";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default function DeletedMembersTab({ t }: { t: any }) {
  const [searchTerm, setSearchTerm] = useState("");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [members, setMembers] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchMembers = async () => {
      try {
        const res = await getBlockedMembers();
        if (res.success && res.data) {
          setMembers(res.data);
        }
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      } catch (error) {
        toast.error("Failed to load blocked members");
      } finally {
        setIsLoading(false);
      }
    };
    fetchMembers();
  }, []);

  const handleUnblock = async (id: string) => {
    try {
      const res = await unblockUser(id);
      if (res.success) {
        setMembers(members.filter((m) => m._id !== id && m.blockedUserId?._id !== id && (m.blockedUserId || m.user || m.userId || m)._id !== id));
        toast.success(res.message || "Member unblocked");
      } else {
        toast.error(res.message || "Failed to unblock member");
      }
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    } catch (error) {
      toast.error("An error occurred");
    }
  };

  const filteredMembers = members.filter((m) => {
    const user = m.blockedUserId || m.blockedUser || m.userId || m.user || m;
    return (user.name || user.displayName || user.username || "").toLowerCase().includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 animate-fade-in">
      <div>
        <h2 className="text-xl font-bold tracking-tight mb-1">
          {t.deleted.title}
        </h2>
      </div>

      {/* Search Input field */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
        <Input
          type="text"
          placeholder={t.deleted.searchPlaceholder}
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="pl-10 h-11 bg-neutral-50/50 border-neutral-200/80 rounded-xl focus-visible:ring-[#429CA8]"
        />
      </div>

      {/* Blocked/Deleted connections stack */}
      <div className="space-y-2">
        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin text-brand" />
          </div>
        ) : filteredMembers.length > 0 ? (
          filteredMembers.map((member) => {
            const user = member.blockedUserId || member.blockedUser || member.userId || member.user || member;
            return (
            <div
              key={member._id || user._id}
              className="flex items-center justify-between p-3 rounded-xl border border-neutral-100 hover:bg-neutral-50/50 transition-colors"
            >
              <div className="flex items-center gap-3">
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={avatarUrl(user.profile || user.image || "default", 150)}
                  alt={user.name || user.displayName}
                  className="w-11 h-11 rounded-full object-cover ring-2 ring-neutral-100"
                />
                <span className="text-sm font-bold text-neutral-700 tracking-wide">
                  {user.name || user.displayName || user.username}
                </span>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => handleUnblock(member._id || user._id)}
                className="h-8 text-xs font-semibold px-3 rounded-lg border-neutral-200 hover:bg-neutral-100 hover:text-neutral-900 text-neutral-600 flex items-center gap-1.5"
              >
                <Ban className="w-3.5 h-3.5" />
                {t.deleted.unblock}
              </Button>
            </div>
          )
        })
        ) : (
          <div className="text-center py-12 text-sm text-neutral-400">
            {t.deleted.empty}
          </div>
        )}
      </div>
    </div>
  );
}

// @/components/settings/tabs/HiddenMembersTab.tsx
"use client";

import React, { useState, useEffect } from "react";
import { Search, Eye, Loader2 } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { getHiddenMembers, unhideUser } from "../action";
import { toast } from "sonner";
import { avatarUrl } from "@/lib/image";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default function HiddenMembersTab({ t }: { t: any }) {
  const [searchTerm, setSearchTerm] = useState("");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [members, setMembers] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  useEffect(() => {
    const fetchMembers = async () => {
      try {
        const res = await getHiddenMembers();
        if (res.success && res.data) {
          setMembers(res.data);
        }
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      } catch (error) {
        toast.error("Failed to load hidden members");
      } finally {
        setIsLoading(false);
      }
    };
    fetchMembers();
  }, []);

  const handleUnhide = async (id: string) => {
    try {
      const res = await unhideUser(id);
      if (res.success) {
        setMembers(members.filter((m) => m._id !== id && m.hiddenUserId?._id !== id && (m.hiddenUserId || m.user || m.userId || m)._id !== id));
        toast.success(res.message || "Member unhidden");
      } else {
        toast.error(res.message || "Failed to unhide member");
      }
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    } catch (error) {
      toast.error("An error occurred");
    }
  };

  const filteredMembers = members.filter((m) => {
    const user = m.userId || m.hiddenUserId || m.user || m;
    return (user.name || user.displayName || user.username || "").toLowerCase().includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 animate-fade-in">
      <div>
        <h2 className="text-xl font-bold tracking-tight mb-1">
          {t.hidden.title}
        </h2>
      </div>

      {/* Search Input field */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400" />
        <Input
          type="text"
          placeholder={t.hidden.searchPlaceholder}
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="pl-10 h-11 bg-neutral-50/50 border-neutral-200/80  rounded-xl focus-visible:ring-[#429CA8]"
        />
      </div>

      {/* Hidden connections stack */}
      <div className="space-y-2">
        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin text-brand" />
          </div>
        ) : filteredMembers.length > 0 ? (
          filteredMembers.map((member) => {
            const user = member.userId || member.hiddenUserId || member.user || member;
            return (
            <div
              key={member._id || user._id}
              className="flex items-center justify-between p-3 rounded-xl border border-neutral-100  hover:bg-neutral-50/50  transition-colors"
            >
              <div className="flex items-center gap-3">
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={avatarUrl(user.profile || user.image || "default", 150)}
                  alt={user.name || user.displayName}
                  className="w-11 h-11 rounded-full object-cover ring-2 ring-neutral-100 "
                />
                <span className="text-sm font-bold text-neutral-700  tracking-wide">
                  {user.name || user.displayName || user.username}
                </span>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => handleUnhide(member._id || user._id)}
                className="h-8 text-xs font-semibold px-3 rounded-lg border-neutral-200  hover:bg-neutral-100 hover:text-neutral-900   text-neutral-600  flex items-center gap-1.5"
              >
                <Eye className="w-3.5 h-3.5" />
                {t.hidden.unhide}
              </Button>
            </div>
          )
        })
        ) : (
          <div className="text-center py-12 text-sm text-neutral-400">
            {t.hidden.empty}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import {
  Heart,
  MessageCircle,
  MoreHorizontal,
  Pencil,
  Share2,
} from "lucide-react";
import { toast } from "sonner";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import { avatarUrl } from "@/lib/image";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { Locale } from "@/i18n/config";
import type { Dictionary } from "@/i18n/dictionaries";
import type { SuccessStory } from "./types";
import {
  brandButtonClass,
  countMedia,
  StoryMediaStrip,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  StoryReactions,
} from "./shared";
import { StoryComments } from "./StoryComments";
import { AddSuccessStoryDialog } from "./AddSuccessStoryDialog";

const relationMap: Record<
  SuccessStory["relationshipStatus"],
  { label: string; className: string }
> = {
  DATING: {
    label: "Dating",
    className: "bg-sky-500/10 text-sky-700 ring-sky-500/20",
  },
  ENGAGED: {
    label: "Engaged",
    className: "bg-rose-500/10 text-rose-700 ring-rose-500/20",
  },
  OTHER: {
    label: "Other",
    className: "bg-amber-500/10 text-amber-700 ring-amber-500/20",
  },
};

function formatDate(date: string, lang: Locale) {
  return new Intl.DateTimeFormat(lang === "pt" ? "pt-BR" : "en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(new Date(date));
}

export function StoryCard({
  lang,
  story,
  currentUser,
  dict,
  liked,
  onLike,
  onComment,
}: {
  lang: Locale;
  story: SuccessStory;
  currentUser: { id: string; username: string; avatarSeed: string };
  dict: Dictionary;
  liked: boolean;
  onLike: (id: string) => Promise<void>;
  onComment: (id: string, text: string) => Promise<void>;
}) {
  const [comment, setComment] = useState("");
  const commentInputId = `story-comment-${story.id}`;
  const mediaCount = countMedia(story);
  const storyHref = `/${lang}/success-stories/details/${story.id}`;
  const meta = relationMap[story.relationshipStatus];
  const previewComments = story.comments.slice(0, 2);

  return (
    <article className="overflow-hidden rounded-[2rem] border border-white/70 bg-white/95 shadow-[0_24px_80px_rgba(15,23,42,0.08)]">
      <div className="p-5 pb-0 sm:p-6 sm:pb-0">
        <div className="flex items-start justify-between gap-4">
          <div className="flex min-w-0 items-center gap-3">
            <Link href={`/${lang}/profile/${story.user.username}`}>
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={avatarUrl(story.user.profileImage, 120)}
                alt={story.user.name}
                className="size-12 rounded-full object-cover ring-2 ring-white"
              />
            </Link>
            <div className="min-w-0">
              <Link
                href={`/${lang}/profile/${story.user.username}`}
                className="block truncate font-semibold text-slate-900 hover:text-[#429CA8]"
              >
                {story.user.name}
              </Link>
              <p className="text-xs text-muted-foreground">
                {formatDate(story.createdAt, lang)}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-1">
            {story.user.id === currentUser.id ? (
              <AddSuccessStoryDialog
                mode="edit"
                story={story}
                title="Edit success story"
                description="Update your story and optionally upload new media."
                userAvatar={avatarUrl(currentUser.avatarSeed, 96)}
                trigger={
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon-sm"
                    className="rounded-full"
                    aria-label="Edit story"
                  >
                    <Pencil className="size-4" />
                  </Button>
                }
              />
            ) : null}

            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon-sm" className="rounded-full">
                  <MoreHorizontal className="size-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem asChild>
                  <Link href={storyHref}>Open details</Link>
                </DropdownMenuItem>
                <DropdownMenuItem
                  onSelect={() =>
                    toast.message("Report sent", {
                      description:
                        "Thanks for helping keep the community safe.",
                    })
                  }
                >
                  Report
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>

        <div className="mt-4 flex flex-wrap items-center gap-2">
          <Badge
            className={cn(
              "rounded-full px-3 py-1 text-[11px] font-semibold tracking-wide ring-1",
              meta.className,
            )}
          >
            {meta.label}
          </Badge>
          {mediaCount > 0 ? (
            <Badge
              variant="outline"
              className="rounded-full border-dashed px-3 py-1 text-[11px] font-semibold"
            >
              {mediaCount} media
            </Badge>
          ) : null}
          <Badge
            variant="outline"
            className="rounded-full border-[#429CA8]/20 px-3 py-1 text-[11px] font-semibold text-[#2b7e87]"
          >
            {story.relationshipStatus}
          </Badge>
        </div>

        <div className="mt-4">
          <Link href={storyHref} className="group block">
            <h2 className="text-2xl font-semibold tracking-tight text-slate-950 group-hover:text-[#429CA8]">
              {story.title}
            </h2>
            <p className="mt-2 text-sm leading-7 text-slate-600 line-clamp-3">
              {story.story}
            </p>
          </Link>
        </div>
      </div>

      <div className="p-5 sm:p-6">
        <StoryMediaStrip media={story.media} storyHref={storyHref} />

        <div className="mt-5 flex gap-3 items-center">
          <Button
            type="button"
            variant="outline"
            className={cn(
              " justify-start gap-2 rounded-[1.25rem] border-[#429CA8]/18 px-4 py-6",
              liked
                ? "bg-[#429CA8] text-[#429CA8]! hover:bg-[#388994]"
                : "text-slate-900",
            )}
            onClick={() => void onLike(story.id)}
          >
            <Heart className={cn("size-4", liked && "fill-current")} />
            <span>{story.likesCount}</span>
          </Button>

          <Button
            type="button"
            variant="outline"
            className=" justify-start gap-2 rounded-[1.25rem] border-[#429CA8]/18 px-4 py-6 text-slate-900"
            onClick={() => {
              const input = document.getElementById(
                commentInputId,
              ) as HTMLTextAreaElement | null;
              input?.focus();
              input?.scrollIntoView({ behavior: "smooth", block: "center" });
            }}
          >
            <MessageCircle className="size-4" />
            <span>{story.commentsCount}</span>
          </Button>

          <Button
            variant="ghost"
            className="rounded-full sm:col-span-2"
            onClick={() =>
              toast.message(dict.successStories.share, {
                description: "Sharing can be wired to your real flow next.",
              })
            }
          >
            <Share2 className="size-4" />
            {dict.successStories.share}
          </Button>
        </div>

        <form
          className="mt-5 flex items-start gap-3 rounded-[1.5rem] border border-[#429CA8]/12 bg-[#429CA8]/6 p-4"
          onSubmit={async (e) => {
            e.preventDefault();
            if (!comment.trim()) return;
            await onComment(story.id, comment.trim());
            setComment("");
          }}
        >
          <Image
            src={avatarUrl(currentUser.avatarSeed, 80)}
            alt=""
            height={80}
            width={80}
            className="size-9 rounded-full object-cover ring-2 ring-white"
          />
          <div className="min-w-0 flex-1">
            <textarea
              id={commentInputId}
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder={dict.successStories.commentPlaceholder}
              className="min-h-20 w-full resize-none rounded-2xl border border-[#429CA8]/15 bg-white px-4 py-3 text-sm outline-none ring-0 placeholder:text-slate-400 focus:border-[#429CA8]"
            />
            <div className="mt-3 flex items-center justify-between gap-3">
              <p className="text-xs text-muted-foreground">
                {dict.successStories.commentHint}
              </p>
              <Button type="submit" className={brandButtonClass}>
                {dict.successStories.comment}
              </Button>
            </div>
          </div>
        </form>

        <div className="mt-5">
          <div className="mb-3 flex items-center justify-between">
            <p className="text-sm font-semibold text-slate-900">
              Recent comments
            </p>
            <p className="text-xs text-muted-foreground">
              {previewComments.length} shown
            </p>
          </div>
          <StoryComments comments={previewComments} compact />
        </div>
      </div>
    </article>
  );
}

